{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "database_call_failed",
      "evidence": [
        {"kind": "log", "sql": "SELECT \"time\", level, message FROM abnormal_logs WHERE service_name='ts-travel2-service' AND level<>'INFO' ORDER BY \"time\" LIMIT 12", "claim": "travel2 logs HikariPool-1 'Connection is not available, request timed out after 30s' followed by SEVERE JDBC connection failures."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, max(duration)/1e6 max_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name IN ('SELECT Trip','TripRepository.findAll','TripRepository.findByRouteId') GROUP BY 1,2,3 ORDER BY 2,3", "claim": "Travel2 'SELECT Trip' and findAll DB spans either finish in about 1ms or fail after about 30s with Error status."},
        {"kind": "metric", "sql": "SELECT 'abn' p, metric, count(*) n, avg(value) avg_v, max(value) max_v FROM abnormal_metrics_sum WHERE service_name='ts-travel2-service' AND metric ILIKE 'db.client%' GROUP BY 1,2 UNION ALL SELECT 'norm', metric, count(*), avg(value), max(value) FROM normal_metrics_sum WHERE service_name='ts-travel2-service' AND metric ILIKE 'db.client%' GROUP BY 1,2 ORDER BY 2,1", "claim": "Travel2 connection pending_requests rises from 0 to about 1.5 and timeouts appear, while pool max stays at 10."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name IN ('ts-route-plan-service') AND span_name IN ('POST','POST /api/v1/routeplanservice/routePlan/quickestRoute') GROUP BY 1,2,3 ORDER BY 1,2,3", "claim": "Route-plan POST spans fail after about 30s (5 errors) while route-plan's own successful POSTs take about 51ms."}
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service') AND span_name IN ('POST','POST /api/v1/travelplanservice/travelPlan/quickest') GROUP BY 1,2,3 ORDER BY 1,2,3", "claim": "Travel-plan POST spans fail after about 30s (5 errors) when their route-plan calls time out."}
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name IN ('POST /api/v1/travelplanservice/travelPlan/quickest','POST /api/v1/travel2service/trips/left') GROUP BY 1,2,3 ORDER BY 1,2,3", "claim": "Dashboard requests to travel-plan and travel2 take about 20s at p50 in the abnormal period, reaching the user-facing tier."}
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name IN ('POST /api/v1/travel2service/trips/left') GROUP BY 1,2,3", "claim": "Dashboard calls to travel2 trips/left slow to about 20s at p50 during the incident."}
      ]
    }
  ]
}

